    if n == 0: return 1
    if n == 1: return 0
    # S_n = (-1)^{n-1} * (n-1)
    return ((-1)**(n-1)) * (n-1)

def sigma_sum(N):
    total_sum = 0
    # Sum_{k=0}^N binom(N, k) * S(N-k) / (k+1)
    from math import comb
    for k in range(N + 1):
        total_sum += comb(N, k) * S(N-k) / (k + 1)
