    perms = list(itertools.permutations(range(n)))
    total_sum = 0
    for p in perms:
        # sign of permutation
        sign = 1
        visited = [False] * n
        num_cycles = 0
        for i in range(n):
            if not visited[i]:
                num_cycles += 1
                curr = i
                while not visited[curr]:
