import itertools

def solve(n):
    total_sum = 0
    perms = list(itertools.permutations(range(n)))
    for p in perms:
        # Calculate sign sigma(p)
        # A permutation is even if it has an even number of even-length cycles
        # Or simply count the number of inversions
        inversions = 0
        for i in range(n):
            for j in range(i + 1, n):
                if p[i] > p[j]:
                    inversions += 1
        sigma = 1 if inversions % 2 == 0 else -1

        # Calculate number of fixed points v(p)
        v = 0
        for i in range(n):
            if p[i] == i:
                v += 1

        total_sum += sigma / (v + 1)
    return total_sum

